-- Private draft contact details are never readable without trusted program context.
ALTER TABLE confsys.program_rooms ENABLE ROW LEVEL SECURITY;
ALTER TABLE confsys.program_rooms FORCE ROW LEVEL SECURITY;
CREATE POLICY program_rooms_manager ON confsys.program_rooms TO confsys_app USING(current_setting('app.program_manage',true)='true') WITH CHECK(current_setting('app.program_manage',true)='true');
CREATE POLICY program_rooms_operator ON confsys.program_rooms TO confsys_migrator USING(true) WITH CHECK(true);
ALTER TABLE confsys.program_room_bookings ENABLE ROW LEVEL SECURITY;
ALTER TABLE confsys.program_room_bookings FORCE ROW LEVEL SECURITY;
CREATE POLICY program_room_bookings_manager ON confsys.program_room_bookings TO confsys_app USING(current_setting('app.program_manage',true)='true') WITH CHECK(current_setting('app.program_manage',true)='true');
CREATE POLICY program_room_bookings_operator ON confsys.program_room_bookings TO confsys_migrator USING(true) WITH CHECK(true);
ALTER TABLE confsys.program_sessions ENABLE ROW LEVEL SECURITY;
ALTER TABLE confsys.program_sessions FORCE ROW LEVEL SECURITY;
CREATE POLICY program_sessions_manager ON confsys.program_sessions TO confsys_app USING(current_setting('app.program_manage',true)='true') WITH CHECK(current_setting('app.program_manage',true)='true');
CREATE POLICY program_sessions_operator ON confsys.program_sessions TO confsys_migrator USING(true) WITH CHECK(true);
ALTER TABLE confsys.program_slots ENABLE ROW LEVEL SECURITY;
ALTER TABLE confsys.program_slots FORCE ROW LEVEL SECURITY;
CREATE POLICY program_slots_manager ON confsys.program_slots TO confsys_app USING(current_setting('app.program_manage',true)='true') WITH CHECK(current_setting('app.program_manage',true)='true');
CREATE POLICY program_slots_operator ON confsys.program_slots TO confsys_migrator USING(true) WITH CHECK(true);
ALTER TABLE confsys.program_person_bookings ENABLE ROW LEVEL SECURITY;
ALTER TABLE confsys.program_person_bookings FORCE ROW LEVEL SECURITY;
CREATE POLICY program_person_bookings_manager ON confsys.program_person_bookings TO confsys_app USING(current_setting('app.program_manage',true)='true') WITH CHECK(current_setting('app.program_manage',true)='true');
CREATE POLICY program_person_bookings_operator ON confsys.program_person_bookings TO confsys_migrator USING(true) WITH CHECK(true);
ALTER TABLE confsys.program_publications ENABLE ROW LEVEL SECURITY;
ALTER TABLE confsys.program_publications FORCE ROW LEVEL SECURITY;
CREATE POLICY program_publications_read ON confsys.program_publications FOR SELECT TO confsys_app USING(current_setting('app.program_manage',true)='true' OR id=(SELECT active_publication_id FROM confsys.program_state WHERE singleton));
CREATE POLICY program_publications_publish ON confsys.program_publications FOR INSERT TO confsys_app WITH CHECK(current_setting('app.program_publish',true)='true');
CREATE POLICY program_publications_operator ON confsys.program_publications TO confsys_migrator USING(true) WITH CHECK(true);
ALTER TABLE confsys.program_state ENABLE ROW LEVEL SECURITY;
ALTER TABLE confsys.program_state FORCE ROW LEVEL SECURITY;
CREATE POLICY program_state_read ON confsys.program_state FOR SELECT TO confsys_app USING(true);
CREATE POLICY program_state_write ON confsys.program_state FOR UPDATE TO confsys_app USING(current_setting('app.program_manage',true)='true') WITH CHECK(current_setting('app.program_manage',true)='true');
CREATE POLICY program_state_operator ON confsys.program_state TO confsys_migrator USING(true) WITH CHECK(true);
